package io.tenvyr.control.engine;

import com.fasterxml.jackson.databind.node.ObjectNode;
import io.tenvyr.platform.*;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;
import static io.tenvyr.control.engine.EngineFacts.*;

/** Timers only ask PostgreSQL what is due. Keyset scans ensure healthy old runs cannot starve later work. */
public final class RuntimeRecoveryService implements AutoCloseable {
  private final Db db;private final DispatchOutboxService outbox;private final ResultInboxService inbox;private final EngineService engine;private final SupervisionService supervision;private final EngineAuthority authority;private final AtomicBoolean recovering=new AtomicBoolean();private ScheduledExecutorService timer;private String cursorId;private Instant cursorCreatedAt;
  public RuntimeRecoveryService(Db db,DispatchOutboxService outbox,ResultInboxService inbox,EngineService engine,SupervisionService supervision,EngineAuthority authority){this.db=db;this.outbox=outbox;this.inbox=inbox;this.engine=engine;this.supervision=supervision;this.authority=authority;}
  public synchronized void start(){if(timer!=null)return;recover(Instant.now());timer=Executors.newSingleThreadScheduledExecutor(r->{Thread t=new Thread(r,"tenvyr-runtime-recovery");t.setDaemon(true);return t;});timer.scheduleAtFixedRate(()->recover(Instant.now()),1000,1000,TimeUnit.MILLISECONDS);}
  public void recover(Instant now){if(!recovering.compareAndSet(false,true))return;try{expireAttempts(now);authority.expireApprovals(now);try{authority.expireDelegation(now);}catch(Exception isolated){System.err.println("Delegation expiry sweep deferred");}try{authority.cancelOrphans(20);}catch(Exception isolated){System.err.println("Delegation orphan cascade deferred");}supervision.evaluate(now);for(String id:findCandidates(now)){try{engine.reconcileExecution(id);}catch(Exception isolated){System.err.println("Execution reconciliation deferred: "+id);}}DispatchOutboxService.Recovery result=outbox.recover();for(String id:result.terminalFailures())engine.reconcileExecution(id,true);}catch(Exception error){System.err.println("Runtime recovery deferred: "+error.getClass().getSimpleName());}finally{recovering.set(false);}}
  private void expireAttempts(Instant now){List<ObjectNode> rows=db.query("SELECT * FROM step_attempts WHERE status IN ('CREATED','DISPATCHED','RUNNING') AND \"deadlineAt\"<=? ORDER BY \"deadlineAt\",id LIMIT 100",now);for(ObjectNode attempt:rows){try{Instant deadline=instant(attempt,"deadlineAt");ObjectNode result=SupervisionService.synthetic(attempt,"DEADLINE_EXCEEDED","Persisted attempt deadline exceeded",deadline==null?now:deadline);ResultInboxService.Application applied=inbox.apply(result,Json.object("adapter","recovery","receivedAt",Protocol.jsInstant(now)));if(applied.disposition().equals("applied")||applied.disposition().equals("duplicate"))engine.reconcileExecution(applied.executionId(),true);}catch(Exception isolated){System.err.println("Attempt deadline application deferred: "+attempt.path("id").asText());}}}
  private List<String> findCandidates(Instant now){String sql="SELECT e.id,e.\"createdAt\" FROM executions e WHERE e.status IN ('PENDING','RUNNING') AND e.\"activePlanRevisionId\" IS NOT NULL AND (EXISTS(SELECT 1 FROM step_executions s WHERE s.\"executionId\"=e.id AND (s.status='PENDING' OR (s.status='READY' AND (s.\"eligibleAt\" IS NULL OR s.\"eligibleAt\"<=?)) OR (s.status='RETRYING' AND (s.\"nextAttemptAt\" IS NULL OR s.\"nextAttemptAt\"<=?)))) OR NOT EXISTS(SELECT 1 FROM step_executions s WHERE s.\"executionId\"=e.id) OR NOT EXISTS(SELECT 1 FROM step_executions s WHERE s.\"executionId\"=e.id AND s.status NOT IN ('COMPLETED','FAILED','SKIPPED','CANCELLED')))";List<Object> args=new ArrayList<>(List.of(now,now));if(cursorId!=null){sql+=" AND (e.\"createdAt\">? OR (e.\"createdAt\"=? AND e.id>?))";args.add(cursorCreatedAt);args.add(cursorCreatedAt);args.add(cursorId);}sql+=" ORDER BY e.\"createdAt\",e.id LIMIT 100";List<ObjectNode> rows=db.query(sql,args.toArray());if(rows.size()<100){cursorId=null;cursorCreatedAt=null;}else{ObjectNode last=rows.get(rows.size()-1);cursorId=last.path("id").asText();cursorCreatedAt=instant(last,"createdAt");}return rows.stream().map(r->r.path("id").asText()).toList();}
  public synchronized void close(){if(timer==null)return;ScheduledExecutorService current=timer;timer=null;current.shutdown();try{if(!current.awaitTermination(10,TimeUnit.SECONDS)){current.shutdownNow();throw new IllegalStateException("Runtime recovery did not drain before shutdown");}}catch(InterruptedException interrupted){current.shutdownNow();Thread.currentThread().interrupt();throw new IllegalStateException("Runtime recovery shutdown interrupted",interrupted);}}
}
